var datum, txt, BerechnungA;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// ------>> Überschuss vorhanden, Strom erhöhen
schedule("*/30 * * * * *", async () => {
  await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / ------ Überschuss - Zyklussteuerung --------');
  if ((getState('go-e.0.unlocked_by').val == 0) && (getState('go-e.0.car').val > 1) && (getState('0_userdata.0.go-e.Timeout').val == 0)) {
    if (getState('alias.0.EM24 Hall Grid.PV_Überschuss').val > 0 && getState('go-e.0.allow_charging').val == 1) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / ------ Überschuss - Zyklus beginnt --------');
      BerechnungA = Math.min(Math.max((getState('alias.0.EM24 Hall Grid.PV_Überschuss').val + getState('go-e.0.energy.power').val * 1000) - getState('0_userdata.0.go-e.minPV').val, 0), 11040);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Überschuss / akt. Überschuss (W): ' + String(BerechnungA));
      if (getState('0_userdata.0.go-e.3P').val == true) {
        BerechnungA = BerechnungA / 3;
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Überschuss / Überschuss pro Phase (W): ' + String(BerechnungA));
      }
      BerechnungA = BerechnungA / 230;
      BerechnungA = Math.round(BerechnungA - 0.5);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Überschuss / berechneter Strom (A): ' + String(BerechnungA));
      BerechnungA = Math.min(Math.max(BerechnungA, getState('0_userdata.0.go-e.minA').val), getState('0_userdata.0.go-e.maxA').val);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Überschuss / begrenzter Strom Min/Max (A): ' + String(BerechnungA));
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Überschuss / akt. Strom (A): ' + String(getState('go-e.0.ampere').val));
      if (BerechnungA > getState('go-e.0.ampere').val) {
        setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, (Math.min(Math.max(BerechnungA, getState('0_userdata.0.go-e.minA').val), getState('0_userdata.0.go-e.maxA').val)));
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Überschuss / neuer Ladestrom (A): ' + String(BerechnungA));
        await wait(1000);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / ------ Überschuss - Zyklus endet --------');
    }
  }
});


